<script module lang="ts">
/**
 * A single show-or-hide section with one trigger (`design/components/collapsible.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/collapsible.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy, type Snippet } from 'svelte'

import * as zag from '@zag-js/collapsible'
import { useMachine } from '@zag-js/svelte'

import {
  Icon,
  agentMember,
  attributes,
  joinSlot,
  normalizeProps,
  useDirection,
  watchEffect,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/collapsible.module.css'

export interface CollapsibleProps {
  /**
   * Strings get the content text style; components keep their own (Accordion's rule).
   */
  children: Snippet
  /**
   * Closed by default, because a disclosure that starts open hides nothing.
   */
  defaultOpen?: boolean
  /**
   * Keeps the closed region's content in the document and `hidden`, so a page's server markup
   * carries it and its state survives a close. Without it the React member leaves closed content
   * out. The generated members keep it in every case.
   */
  keepMounted?: boolean
  /**
   * The trigger's text, naming what is disclosed in the product's words.
   */
  label: string
  onOpenChange?: (open: boolean) => void
  /**
   * Controlled state, paired with `onOpenChange` as in Radix.
   */
  open?: boolean
}
</script>

<script lang="ts">
let {
  children,
  defaultOpen = false,
  keepMounted,
  label: labelOwn,
  onOpenChange,
  open,
}: CollapsibleProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({ label: labelOwn }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
let trigger = $state<HTMLElement | null>(null)
const documentDirection = useDirection()
const service = useMachine(
  zag.machine,
  () =>
    ({
      id: uid,
      dir: documentDirection.current,
      open: open,
      defaultOpen: defaultOpen,
      onOpenChange: (details) => {
        onOpenChange?.(details.open)
      },
    }) as Partial<zag.Props>,
)
const api = $derived(zag.connect(service, normalizeProps))
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'Collapsible',
    element: () => trigger,
    state: () => ({ open: api.open }),
    actions: {
      open: () => api.open || api.setOpen(true),
      close: () => api.open && api.setOpen(false),
    },
  })
  release1 = () => {
    ran()
  }
}
watchEffect(effect1)
onDestroy(() => release1?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div {...attributes(api.getRootProps())} class={styles.root} data-member="collapsible"
    ><button bind:this={trigger} {...attributes(api.getTriggerProps())} class={styles.trigger}
      ><span class={styles.label}>{label}</span
      ><span class={styles.chevron}><Icon name="down" size="sm" /></span
    ></button
    ><div
      {...attributes(api.getContentProps())}
      class={styles.content}
      style:--radix-collapsible-content-height={Object(api.getContentProps().style)['--height']}
      ><div class={styles.inner}>{@render children?.()}</div
    ></div
  ></div
>{/if
}{@render joined.end?.()}
